    public static function evaluateAlerts(App $a,?\DateTimeImmutable $at=null):void
    {
        $at=($at??new \DateTimeImmutable('now'))->setTimezone(new \DateTimeZone('UTC'));$now=(float)$at->format('U.u')*1000;$stamp=EventPrivacy::iso($now);$hour=EventPrivacy::iso(floor($now/3600000)*3600000);
        foreach($a->store->list('alert_rules') as $candidate)Governance::siteGuard($a,$candidate['site_id'],function()use($a,$candidate,$at,$now,$stamp,$hour){$rule=$a->store->get('alert_rules',$candidate['id']);if(!$rule||($rule['disabled']??false)||EventPrivacy::millis($rule['next_at']??'1970-01-01')>$now||EventPrivacy::millis($rule['silenced_until']??'1970-01-01')>$now)return;$site=$a->store->get('sites',$rule['site_id']);if(!$site)return;$s=$site['id'];$cfg=$rule['config']??[];$kind=$rule['kind'];$tz=new \DateTimeZone($site['timezone']??'UTC');$today=$at->setTimezone($tz)->setTime(0,0);$abnormal=false;$detail=['kind'=>$kind];$available=true;
            if($kind==='offline'){$latest=$site['last_event_at']??null;$abnormal=$latest===null||EventPrivacy::millis($latest)<$now-86400000;$detail+=['last_event_at'=>$latest];}
            elseif($kind==='storage'){$bytes=(int)($a->db->one("SELECT COALESCE(sum(octet_length(body)),0) b FROM documents WHERE kind='events' AND site_id=?",[$s])['b']??0);$abnormal=$bytes>(float)($cfg['max_bytes']??1e9);$detail+=['bytes'=>$bytes,'source'=>'mysql','storageAlertStatus'=>'supported'];}
            elseif($kind==='traffic'){
                $metric=($cfg['metric']??'pv')==='uv'?'uv':'pv';$end=floor($now/3600000)*3600000;$state=$a->store->get('aggregation_state',$s)??[];$ready=isset($state['watermark'])&&(int)($state['processed_generation']??0)>0&&($state['generation']??null)===($state['processed_generation']??null);
                $read=Analytics::read($a,$s);$history=[];$current=null;for($i=0;$i<=28;$i++){$begin=$end-3600000-$i*86400000;if(isset($site['created_at'])&&EventPrivacy::millis($site['created_at'])>$begin)continue;$row=AnalysisEngine::stats($read['site'],$read['events'],EventPrivacy::iso($begin),EventPrivacy::iso($begin+3600000),[],[],[],microtime(true)*1000,$read['context']);if(($row['metricCoverage']['events']??$row['coverage'])!==1||!is_numeric($row['totals'][$metric]??null))continue;if($i===0)$current=(float)$row['totals'][$metric];else $history[]=(float)$row['totals'][$metric];}
                $available=$ready&&$current!==null&&count($history)>=7;$mean=array_sum($history)/max(1,count($history));$variance=array_sum(array_map(fn($n)=>($n-$mean)**2,$history))/max(1,count($history));$abnormal=$available&&$mean>0&&abs($current-$mean)/$mean>(float)($cfg['deviation']??0.5);$detail+=['metric'=>$metric,'current'=>$current,'mean'=>$mean,'z_score'=>$variance>0?($current-$mean)/sqrt($variance):null,'observed_hour'=>EventPrivacy::iso($end-3600000),'baseline_days'=>28,'baseline_samples'=>count($history),'coverage'=>$available?1:0,'watermark'=>$state['watermark']??null,'processed_generation'=>$state['processed_generation']??null,'current_generation'=>$state['generation']??null,'coverage_method'=>'published_snapshot_matching_intake_generation','distinct_method'=>'exact_per_hour_set'];
            }
            elseif($kind==='goal'){$stats=Analytics::stats($a,$s,['from'=>$today->format('c'),'to'=>$stamp]);$available=$stats['coverage']===1;$count=0;if(isset($cfg['goal_id']))$count=(int)(((array)$stats['goals'])[$cfg['goal_id']]??0);else foreach($stats['events'] as $event)if(($event['name']??'')===(string)($cfg['event']??''))$count+=(int)$event['count'];$abnormal=$count>=(float)($cfg['threshold']??1);$detail+=['count'=>$count,'coverage'=>$stats['coverage'],'watermark'=>$stats['watermark'],'rangeStatus'=>$stats['rangeStatus'],'storage'=>$stats['storage']];}
            elseif($kind==='funnel'){$definition=$a->store->get('funnels',(string)($cfg['funnel_id']??''));if($definition&&($definition['site_id']??null)===$s){$yesterday=$today->modify('-1 day');$priorDay=$today->modify('-2 days');$latest=Analytics::stats($a,$s,['from'=>$yesterday->format('c'),'to'=>$today->format('c')]);$prior=Analytics::stats($a,$s,['from'=>$priorDay->format('c'),'to'=>$yesterday->format('c')]);$available=$latest['coverage']===1&&$prior['coverage']===1&&$latest['funnelStatus']==='supported'&&$prior['funnelStatus']==='supported';$counts=((array)$latest['funnels'])[$definition['id']]??[];$before=((array)$prior['funnels'])[$definition['id']]??[];$steps=[];foreach($counts as $i=>$n)if($i>0){$c=($counts[$i-1]??0)?$n/$counts[$i-1]:0;$p=($before[$i-1]??0)?($before[$i]??0)/$before[$i-1]:0;$steps[]=['step'=>$i,'current'=>$c,'previous'=>$p];if((!(int)($cfg['step']??0)||(int)$cfg['step']===$i)&&$p>0&&$c<$p*(1-(float)($cfg['drop_threshold']??0.3)))$abnormal=true;}$detail+=['current'=>($counts[0]??0)?end($counts)/$counts[0]:0,'previous'=>($before[0]??0)?end($before)/$before[0]:0,'steps'=>$steps,'day'=>$yesterday->format('Y-m-d'),'previous_day'=>$priorDay->format('Y-m-d'),'coverage'=>min($latest['coverage'],$prior['coverage']),'watermark'=>$latest['watermark'],'storage'=>$latest['storage']];}}
            elseif($kind==='serp'){$groups=[];$floor=$today->modify('-1 day')->format('Y-m-d');$ceiling=$today->format('Y-m-d');foreach($a->store->list('rank_history',$s) as $rank){if(isset($cfg['keyword'])&&$rank['keyword']!==$cfg['keyword'])continue;if(isset($cfg['provider'])&&$rank['provider']!==$cfg['provider'])continue;$groups[$rank['provider']."\0".$rank['keyword']][]=$rank;}$changes=[];$threshold=max(1,(float)($cfg['threshold']??5));foreach($groups as $ranks){usort($ranks,fn($x,$y)=>strcmp($y['day'],$x['day']));if(count($ranks)<2)continue;[$current,$previous]=$ranks;if($current['day']<$floor||$current['day']>$ceiling||(strtotime($current['day'])-strtotime($previous['day']))>2*86400)continue;$delta=($current['position']??100)-($previous['position']??100);if(abs($delta)>=$threshold)$changes[]=['keyword'=>$current['keyword'],'provider'=>$current['provider'],'day'=>$current['day'],'position'=>$current['position'],'previous_position'=>$previous['position'],'delta'=>$delta];}$abnormal=(bool)$changes;$detail+=['changes'=>$changes,'threshold'=>$threshold,'unranked_position'=>100];}
            if(!$available){$rule['next_at']=EventPrivacy::iso($now+60000);$rule['evaluation']=['status'=>'awaiting_complete_coverage']+$detail;$a->store->put('alert_rules',$rule['id'],$rule,$s);return;}
            $sameHour=($cfg['_last_hour']??null)===$hour;$priorHour=EventPrivacy::iso(EventPrivacy::millis($hour)-3600000);$consecutive=$sameHour?(int)($rule['consecutive']??0):($abnormal?(($cfg['_last_hour']??null)===$priorHour?(int)($rule['consecutive']??0)+1:1):0);$trigger=!$sameHour&&$consecutive>=($kind==='traffic'?2:1)&&(!isset($rule['last_fired'])||$now-EventPrivacy::millis($rule['last_fired'])>86400000);
            if($trigger)self::enqueueNotification($a,$s,$rule['channel_id'],['title'=>'白泽告警','rule_id'=>$rule['id'],'aggregationEpoch'=>External::epoch($a,$s)]+$detail,'alert:'.$rule['id'].':'.substr($stamp,0,13));$rule['next_at']=EventPrivacy::iso($now+3600000);$rule['consecutive']=$consecutive;if($trigger)$rule['last_fired']=$stamp;$rule['config']['_last_hour']=$hour;$rule['evaluation']=['status'=>'evaluated','abnormal'=>$abnormal]+$detail;$a->store->put('alert_rules',$rule['id'],$rule,$s);
        });
    }
    public static function register(App $a,Router $r):void
    {
        $r->add('GET','/api/admin/operations',function(Http $h)use($a){$a->auth->admin($h);return ['runtime'=>'PHP '.PHP_VERSION,'database'=>$a->db->one('SELECT VERSION() version')['version'],'schema'=>$a->db->all('SELECT version FROM schema_migrations'),'jobs'=>array_count_values(array_column($a->store->list('notification_jobs'),'status')),'journal_records'=>count(Governance::journal($a->config,true))];});
        $base='/api/v1/sites/:siteId';Governance::route($a,$r,'GET',$base.'/storage/history',function(Http $h)use($a){$s=$h->params['siteId'];$a->auth->authorize($h,$s,'admin');return ['authority'=>'mysql','configured'=>true,'manifests'=>$a->store->list('history_manifests',$s)];});
        Governance::route($a,$r,'POST',$base.'/storage/history/capture',function(Http $h)use($a){$s=$h->params['siteId'];$a->auth->authorize($h,$s,'admin');return $a->db->transaction(function()use($a,$s){$a->db->lock('site:'.$s);$eventCount=(int)($a->db->one("SELECT COUNT(*) n FROM documents WHERE kind='events' AND site_id=?",[$s])['n']??0);if($eventCount>Analytics::EVENT_LIMIT)Http::error(409,'history_event_limit','保留明细超过历史捕获精确重建上限 100000 条，本次未发布快照；完整灾备请使用加密实例备份');Worker::aggregate($a,$s);$aggregation=$a->store->get('aggregation_state',$s)??[];if(($aggregation['generation']??null)!==($aggregation['processed_generation']??null)||!isset($aggregation['watermark']))Http::error(409,'history_aggregation_pending');$data=self::exportSite($a,$s,true);$id=Store::uuid();$namespace=Store::uuid();$rows=[];foreach($data['tables'] as $kind=>$records)if(str_starts_with($kind,'stats_')||(str_starts_with($kind,'history_')&&!in_array($kind,['history_manifests','history_namespaces','history_backups'],true))||in_array($kind,['visitor_first_seen','goals','funnels'],true))$rows[$kind]=$records;$siteSnapshot=self::safeConfig($a->store->get('sites',$s)??[]);$siteSnapshot['first_seen_history_complete']=($siteSnapshot['first_seen_history_complete']??true)===true;$capturedAt=Store::now();$manifest=['id'=>$id,'site_id'=>$s,'namespace'=>$namespace,'status'=>'published','created_at'=>$capturedAt,'captured_at'=>$capturedAt,'aggregation'=>array_intersect_key($aggregation,array_flip(['generation','processed_generation','watermark','epoch','processed_events','updated_at'])),'tables'=>$rows,'site_snapshot'=>$siteSnapshot,'site'=>$siteSnapshot,'references'=>array_column($a->store->list('history_manifests',$s),'id'),'sha256'=>hash('sha256',self::json($rows))];$a->store->put('history_manifests',$id,$manifest,$s);return ['manifest'=>$manifest];});});
        Governance::route($a,$r,'POST',$base.'/storage/history/:id/backup',function(Http $h)use($a){$s=$h->params['siteId'];$a->auth->authorize($h,$s,'admin');if(!preg_match('/^[a-f0-9-]{36}$/D',$h->params['id']))Http::error(400,'history_id_invalid');$v=$a->store->get('history_manifests',$h->params['id']);if(!$v||$v['site_id']!==$s)Http::error(404,'history_missing');$path=$a->config['data_dir'].'/history/'.$v['id'].'.enc';$sealed=Security::seal(self::json($v),$a->config);self::writeFile($path,$sealed);Governance::write($a,$s,'history_backups',['id'=>$v['id'],'site_id'=>$s,'path'=>$path,'sha256'=>hash('sha256',$sealed),'created_at'=>Store::now()]);return ['id'=>$v['id'],'bytes'=>strlen($sealed),'integrity'=>$v['sha256'],'rows'=>array_sum(array_map('count',$v['tables']))];});
        Governance::route($a,$r,'POST',$base.'/storage/history/:id/restore',function(Http $h)use($a){$s=$h->params['siteId'];$a->auth->authorize($h,$s,'admin');if(!preg_match('/^[a-f0-9-]{36}$/D',$h->params['id']))Http::error(400,'history_id_invalid');$ns=Governance::text($h->body['namespace']??null,64);if(!preg_match('/^[a-f0-9-]{36}$/D',$ns))Http::error(400,'history_namespace_invalid');return $a->db->transaction(function()use($a,$h,$s,$ns){$a->db->lock('site:'.$s);$path=$a->config['data_dir'].'/history/'.$h->params['id'].'.enc';if(!is_file($path))Http::error(404,'history_backup_missing');$v=json_decode(Security::unseal((string)file_get_contents($path),$a->config),true,512,JSON_THROW_ON_ERROR);if(($v['site_id']??null)!==$s||!hash_equals($v['sha256'],hash('sha256',self::json($v['tables']))))Http::error(409,'history_integrity_invalid');if($a->store->list('privacy_tombstones',$s))Http::error(409,'history_restore_requires_privacy_rebuild','存在删除边界；不能恢复缺少可逐人验证证据的历史聚合');$id=Store::uuid();$v['source_manifest']=$v['id'];$v['id']=$id;$v['namespace']=$ns;$v['captured_at']=$v['captured_at']??$v['source_created_at']??$v['created_at'];$v['source_created_at']=$v['source_created_at']??$v['created_at'];$v['restored_at']=Store::now();$v['created_at']=$v['restored_at'];$a->store->put('history_namespaces',$ns,$v,$s);return ['manifest'=>$v,'namespace'=>$ns,'activeStatisticsChanged'=>false];});});
    }
